"use server";

// Server actions for connecting/disconnecting a customer's own Anthropic API
// key (BYOK). Only async functions are exported (Next.js "use server" rule).
// The stored key is AES-256-GCM encrypted at rest and NEVER returned to the
// client — callers can only learn whether a key is connected, not its value.

import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser } from "./auth";
import { encryptSecret } from "./crypto-box";

// Anthropic keys look like `sk-ant-api03-...` — a stable, recognizable prefix
// followed by an opaque token. We validate shape only (never call the API here).
const ANTHROPIC_KEY_RE = /^sk-ant-[A-Za-z0-9_-]{20,}$/;

export async function connectAnthropicKey(key: string): Promise<{ error?: string; ok?: boolean }> {
  const user = await requireUser();

  const clean = (key ?? "").trim();
  if (!clean) {
    return { error: "Please paste your Anthropic API key." };
  }
  if (!ANTHROPIC_KEY_RE.test(clean)) {
    return { error: 'That doesn’t look like an Anthropic API key — it should start with "sk-ant-".' };
  }

  await db.user.update({
    where: { id: user.id },
    data: { anthropicKeyEnc: encryptSecret(clean) },
  });

  await db.auditLog
    .create({ data: { userId: user.id, action: "user.anthropic_key_connect", detail: "connected" } })
    .catch(() => {});

  revalidatePath("/dashboard/build");
  return { ok: true };
}

export async function disconnectAnthropicKey(): Promise<{ ok: boolean }> {
  const user = await requireUser();

  await db.user.update({
    where: { id: user.id },
    data: { anthropicKeyEnc: null },
  });

  await db.auditLog
    .create({ data: { userId: user.id, action: "user.anthropic_key_disconnect", detail: "disconnected" } })
    .catch(() => {});

  revalidatePath("/dashboard/build");
  return { ok: true };
}

/** Whether the current user has a stored key. Returns a boolean only — never the key. */
export async function hasAnthropicKey(): Promise<boolean> {
  const user = await requireUser();
  const u = await db.user.findUnique({
    where: { id: user.id },
    select: { anthropicKeyEnc: true },
  });
  return Boolean(u?.anthropicKeyEnc);
}

